//! Round 39b „User interface German and English, outputs and help“, written in interface S1 (contract §4.3); owners
//! of the checked pages: hilfe_en_1 and hilfe_en_2 (they do not edit this file, a wrong check is reported).
//!
//! Every English page `site/content/en/**/*.md` is the translation of the German page with the same relative path
//! (Hugo pairs translations by path): same `weight` and non-text front matter, no `aliases`, the same `{#anchor}`
//! ids, the same pictures in the same order (each with an English `alt`), no German letters or German quotation
//! marks in prose, and internal links under `/en/`. The completeness check (every German page has an English page)
//! is added by the integrator after both hilfe branches are merged.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

/// Front matter keys that carry text and are translated; every other key must be equal to German.
const TEXT_KEYS: [&str; 4] = ["title", "description", "claim", "lead"];

/// German letters and German quotation marks that must not appear in English prose.
const GERMAN_CHARS: [char; 9] = ['ä', 'ö', 'ü', 'Ä', 'Ö', 'Ü', 'ß', '„', '“'];

/// Pages exempt from the letter check: proper names (address of the provider).
const LETTER_EXEMPT: [&str; 1] = ["impressum.md"];

fn content_dir(lang: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../site/content").join(lang)
}

/// All `*.md` files under `dir`, as paths relative to `dir` with `/`, sorted; a missing directory gives none.
fn markdown_files(dir: &Path) -> Vec<String> {
    fn walk(base: &Path, dir: &Path, out: &mut Vec<String>) {
        let Ok(entries) = std::fs::read_dir(dir) else { return };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(base, &path, out);
            } else if path.extension().is_some_and(|ext| ext == "md") {
                let relative = path.strip_prefix(base).expect("walked below base");
                out.push(relative.components().map(|c| c.as_os_str().to_string_lossy()).collect::<Vec<_>>().join("/"));
            }
        }
    }
    let mut out = Vec::new();
    walk(dir, dir, &mut out);
    out.sort();
    out
}

/// Splits a page into its front matter (`key: value`, raw values trimmed) and the body after it.
fn split_page(page: &str) -> (BTreeMap<String, String>, String) {
    let mut lines = page.lines();
    let mut front = BTreeMap::new();
    if lines.next() != Some("---") {
        return (front, page.to_owned());
    }
    for line in lines.by_ref() {
        if line == "---" {
            break;
        }
        if let Some((key, value)) = line.split_once(':')
            && !key.starts_with(' ')
        {
            front.insert(key.trim().to_owned(), value.trim().to_owned());
        }
    }
    (front, lines.collect::<Vec<_>>().join("\n"))
}

/// Front matter without the translated text keys and without `aliases` (German only).
fn non_text_fields(front: &BTreeMap<String, String>) -> BTreeMap<String, String> {
    front
        .iter()
        .filter(|(key, _)| !TEXT_KEYS.contains(&key.as_str()) && key.as_str() != "aliases")
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect()
}

/// The `{#id}` anchors of a body.
fn anchors(body: &str) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    let mut rest = body;
    while let Some(start) = rest.find("{#") {
        let after = &rest[start + 2..];
        let Some(end) = after.find('}') else { break };
        out.insert(after[..end].to_owned());
        rest = &after[end + 1..];
    }
    out
}

/// Value of the attribute `name="…"` inside one shortcode call.
fn attribute<'a>(call: &'a str, name: &str) -> Option<&'a str> {
    let marker = format!(" {name}=\"");
    let start = call.find(&marker)? + marker.len();
    let end = call[start..].find('"')?;
    Some(&call[start..start + end])
}

/// The picture calls of a body in order: (`hilfebild`, name) or (`bild`, datei), plus their `alt`.
fn pictures(body: &str) -> Vec<((String, String), Option<String>)> {
    let mut found: Vec<(usize, &str, &str)> = Vec::new();
    for (kind, opening) in [("hilfebild", "{{< hilfebild "), ("bild", "{{< bild ")] {
        let mut from = 0;
        while let Some(at) = body[from..].find(opening) {
            let start = from + at;
            let end = body[start..].find(">}}").map_or(body.len(), |end| start + end);
            found.push((start, kind, &body[start..end]));
            from = end;
        }
    }
    found.sort_by_key(|(start, _, _)| *start);
    found
        .into_iter()
        .map(|(_, kind, call)| {
            let id_attribute = if kind == "hilfebild" { "name" } else { "datei" };
            let id = attribute(call, id_attribute).unwrap_or_default().to_owned();
            ((kind.to_owned(), id), attribute(call, "alt").map(str::to_owned))
        })
        .collect()
}

/// Prose lines (1-based number, text) outside fenced code blocks, with inline code spans removed.
fn prose_lines(page: &str) -> Vec<(usize, String)> {
    let mut out = Vec::new();
    let mut fenced = false;
    for (index, line) in page.lines().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            fenced = !fenced;
            continue;
        }
        if fenced {
            continue;
        }
        let outside_code: String = line.split('`').step_by(2).collect();
        out.push((index + 1, outside_code));
    }
    out
}

/// Root-relative markdown link targets `](/…)` of a body.
fn root_links(body: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = body;
    while let Some(start) = rest.find("](/") {
        let after = &rest[start + 2..];
        let end = after.find(')').unwrap_or(after.len());
        out.push(after[..end].to_owned());
        rest = &after[end..];
    }
    out
}

fn read(path: &Path) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|error| panic!("{} cannot be read: {error}", path.display()))
}

#[test]
fn the_german_help_is_where_the_english_pages_are_compared_against() {
    let german = markdown_files(&content_dir("de"));
    assert!(
        german.iter().any(|path| path == "_index.md") && german.iter().any(|path| path == "hilfe/_index.md"),
        "the checks below compare against site/content/de; without it every English check would pass vacuously: \
         {german:?}"
    );
}

#[test]
fn every_english_page_translates_a_german_page_of_the_same_path() {
    let (de, en) = (content_dir("de"), content_dir("en"));
    let mut problems = Vec::new();
    for path in markdown_files(&en) {
        let german = de.join(&path);
        if !german.is_file() {
            problems.push(format!("{path}: no German page site/content/de/{path} (Hugo pairs translations by path)"));
            continue;
        }
        let (front_en, body_en) = split_page(&read(&en.join(&path)));
        let (front_de, body_de) = split_page(&read(&german));
        for key in ["title", "description"] {
            if front_en.get(key).is_none_or(|value| value.trim_matches('"').trim().is_empty()) {
                problems.push(format!("{path}: front matter `{key}` missing or empty (shown as page title/meta)"));
            }
        }
        if front_en.contains_key("aliases") {
            problems.push(format!("{path}: `aliases` in an English page (the old addresses stay German only)"));
        }
        if non_text_fields(&front_en) != non_text_fields(&front_de) {
            problems.push(format!(
                "{path}: weight and non-text front matter must equal German (order and layout follow them): en {:?}, \
                 de {:?}",
                non_text_fields(&front_en),
                non_text_fields(&front_de)
            ));
        }
        if anchors(&body_en) != anchors(&body_de) {
            problems.push(format!(
                "{path}: `{{#…}}` anchors differ from German (links into the page keep the same fragment): en {:?}, \
                 de {:?}",
                anchors(&body_en),
                anchors(&body_de)
            ));
        }
        let pictures_en = pictures(&body_en);
        let ids_en: Vec<_> = pictures_en.iter().map(|(id, _)| id.clone()).collect();
        let ids_de: Vec<_> = pictures(&body_de).into_iter().map(|(id, _)| id).collect();
        if ids_en != ids_de {
            problems.push(format!(
                "{path}: picture calls differ from German (same pictures in the same order): en {ids_en:?}, de \
                 {ids_de:?}"
            ));
        }
        for ((kind, id), alt) in &pictures_en {
            if alt.as_deref().is_none_or(|alt| alt.trim().is_empty()) {
                problems.push(format!("{path}: {kind} `{id}` without alt text (screen readers need it)"));
            }
        }
    }
    assert!(problems.is_empty(), "English pages do not match their German originals:\n{}", problems.join("\n"));
}

#[test]
fn english_prose_has_no_german_letters_or_quotation_marks() {
    let en = content_dir("en");
    let mut problems = Vec::new();
    for path in markdown_files(&en) {
        if LETTER_EXEMPT.contains(&path.as_str()) {
            continue;
        }
        for (number, line) in prose_lines(&read(&en.join(&path))) {
            if line.contains(GERMAN_CHARS) {
                problems.push(format!("{path}:{number}: {line}"));
            }
        }
    }
    assert!(
        problems.is_empty(),
        "German letters or „“ in English prose (left-over German; code blocks and inline code are exempt):\n{}",
        problems.join("\n")
    );
}

#[test]
fn english_pages_link_internally_under_en() {
    let en = content_dir("en");
    let mut problems = Vec::new();
    for path in markdown_files(&en) {
        let (_, body) = split_page(&read(&en.join(&path)));
        for target in root_links(&body) {
            if !(target.starts_with("/en/") || target.starts_with("/apt/")) {
                problems.push(format!("{path}: link to {target}"));
            }
        }
    }
    assert!(
        problems.is_empty(),
        "root-relative links in English pages must stay in English (/en/…) or point to static files (/apt/…):\n{}",
        problems.join("\n")
    );
}

#[test]
fn the_helpers_read_pages_as_the_checks_assume() {
    let page = "---\ntitle: \"T\"\nweight: 30\naliases: [\"/x/\"]\ninhalt: true\n---\n\n## A {#a}\n\n\
                {{< hilfebild name=\"n1\" alt=\"one\" titel=\"t\" >}}\ntext `code ä` and [l](/en/hilfe/#a)\n\
                {{< bild datei=\"b.png\" alt=\"\" >}}\n```sh\nGröße\n```\nende ß\n";
    let (front, body) = split_page(page);
    assert_eq!(front.get("weight").map(String::as_str), Some("30"), "front matter values are read raw");
    assert_eq!(
        non_text_fields(&front).keys().collect::<Vec<_>>(),
        ["inhalt", "weight"],
        "title is translated text and aliases are German only; both are left out of the comparison"
    );
    assert_eq!(anchors(&body), BTreeSet::from(["a".to_owned()]), "heading ids are found");
    let found = pictures(&body);
    assert_eq!(
        found.iter().map(|(id, _)| id.clone()).collect::<Vec<_>>(),
        [("hilfebild".to_owned(), "n1".to_owned()), ("bild".to_owned(), "b.png".to_owned())],
        "both shortcodes are found in page order"
    );
    assert_eq!(found[1].1.as_deref(), Some(""), "an empty alt is read as empty and then reported");
    let prose: Vec<String> = prose_lines(page).into_iter().map(|(_, line)| line).collect();
    assert!(!prose.iter().any(|line| line.contains("Größe")), "fenced code is not prose");
    assert!(!prose.iter().any(|line| line.contains('ä')), "inline code is not prose");
    assert!(prose.iter().any(|line| line.contains('ß')), "ordinary lines are prose");
    assert_eq!(root_links(&body), ["/en/hilfe/#a"], "markdown link targets are read up to the closing parenthesis");
}
